rules:
  - id: parameterized-sql-only-java
    languages: [java]
    severity: ERROR
    message: SQL is built by concatenating or formatting values into the query string; use a PreparedStatement with ? placeholders or an ORM query parameter instead.
    metadata:
      category: security
    pattern-either:
      - patterns:
          - pattern-either:
              - pattern: $OBJ.$METHOD(..., $A + $B, ...)
              - pattern: $OBJ.$METHOD(..., String.format(...), ...)
          - metavariable-regex:
              metavariable: $METHOD
              regex: '^(execute|executeQuery|executeUpdate|executeLargeUpdate|prepareStatement|prepareCall|createQuery|createNativeQuery|addBatch)$'
      - patterns:
          - pattern-either:
              - pattern: $T $Q = $LIT + $X;
              - pattern: $Q = $LIT + $X;
          - metavariable-regex:
              metavariable: $LIT
              regex: '(?i)^"\s*(select|insert|update|delete|merge|create|drop|alter)\b'
      - patterns:
          - pattern: $T $Q = String.format($LIT, ...);
          - metavariable-regex:
              metavariable: $LIT
              regex: '(?i)^"\s*(select|insert|update|delete|merge|create|drop|alter)\b'
